WITH cleaned AS (SELECT *, CONCAT(carrier, ' - ', status) AS carrier_status, INITCAP(TRIM(carrier)) AS carrier_title, COALESCE(carrier, 'DIRECT') AS carrier_filled FROM shipments WHERE delivered_date > DATE '2023-05-03' AND carrier IS NOT NULL), valid AS (SELECT id, carrier, shipped_date, delivered_date, cost, carrier_title, DATEDIFF(shipped_date, delivered_date) AS days_delivered_date_to_shipped_date, COALESCE(carrier, 'OTHER') AS resolved_carrier FROM cleaned WHERE carrier IS NOT NULL AND carrier IN ('FedEx', 'DHL', 'UPS')), cleaned_shipments AS (SELECT *, DATEDIFF(CURRENT_DATE(), delivered_date) AS days_since_delivered_date, UPPER(carrier) AS carrier_upper, COALESCE(carrier, 'OTHER') AS resolved_carrier_2 FROM valid WHERE carrier IS NOT NULL AND carrier IS NOT DISTINCT FROM 'DHL'), valid_shipments AS (SELECT *, DATEDIFF(delivered_date, shipped_date) AS days_shipped_date_to_delivered_date, DATE_TRUNC('YEAR', delivered_date) AS delivered_date_period FROM cleaned_shipments WHERE carrier IS NOT NULL), latest AS (SELECT id, cost, carrier_title, days_delivered_date_to_shipped_date, delivered_date_period FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY delivered_date_period NULLS LAST, id) AS row_num FROM valid_shipments) x WHERE row_num = 1), with_windows AS (SELECT *, SUM(cost) OVER (ORDER BY days_delivered_date_to_shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cost, LAG(days_delivered_date_to_shipped_date, 1, 0) OVER w_ordered AS prev_days_delivered_date_to_shipped_date, NTILE(5) OVER w_ordered AS days_delivered_date_to_shipped_date_bucket FROM latest WINDOW w_ordered AS (ORDER BY days_delivered_date_to_shipped_date, id)) SELECT id, cost, cumulative_cost, days_delivered_date_to_shipped_date_bucket FROM with_windows ORDER BY cumulative_cost DESC, cost;
